"use strict";(globalThis.webpackChunksap_architecture_center=globalThis.webpackChunksap_architecture_center||[]).push([[72761],{73472(e){e.exports=JSON.parse('{"tag":{"label":"Security","permalink":"/docs/tags/security","description":"Protect your data and applications with comprehensive security solutions.","allTagsPath":"/docs/tags","count":19,"items":[{"id":"ref-arch/RA0019/authentication-and-single-sign-on/id-ra0019-1","title":"Authentication with SAP Cloud Identity Services","description":"This reference architecture describes the authentication flows for SAP SaaS via the SAP Cloud Identity Services - Identity Authentication.","permalink":"/docs/ref-arch/20c6b29b1e/1"},{"id":"ref-arch/RA0019/authorization-design/id-ra0019-3","title":"Authorization with SAP Cloud Identity Services","description":"Centralize identity lifecycle management with SAP Cloud Identity Services for secure authorization across SAP SaaS solutions.","permalink":"/docs/ref-arch/20c6b29b1e/3"},{"id":"ref-arch/RA0007/mt-tco/id-ra0007-5","title":"Cost of Ownership","description":"Explore strategies to optimize the total cost of ownership for multitenant SAP applications, covering platform, maintenance, and resource allocation costs.","permalink":"/docs/ref-arch/d31bedf420/5"},{"id":"ref-arch/RA0031/id-ra0031","title":"Decentralized Identity Verification","description":"Decentralized Identity Verification (DIV) is a multi-tenant SAP BTP service that enables enterprise applications to use Self-Sovereign Identity (SSI) for secure, privacy-preserving inter-company communications.","permalink":"/docs/ref-arch/08N_yhbT"},{"id":"ref-arch/RA0031/bring-your-own-wallet/id-ra0031-2","title":"DIV \u2013 Bring Your Own Wallet","description":"Bring Your Own Wallet (BYOW) describes the provisioning model in which a dataspace member self-provisions SAP DIV on SAP BTP instead of receiving a wallet from the Operating Company. The operator still issues the membership credential, which is pushed to the member-hosted DIV wallet.","permalink":"/docs/ref-arch/08N_yhbT/2"},{"id":"ref-arch/RA0031/product-carbon-footprint-use-case/id-ra0031-3","title":"DIV \u2013 Product Carbon Footprint Use Case","description":"This reference architecture describes how SAP Decentralized Identity Verification (DIV) enables secure, privacy-preserving exchange of Product Carbon Footprint (PCF) data between supply chain partners using Self-Sovereign Identity and Verifiable Credentials, with each member provisioning their own DIV wallet (Bring Your Own Wallet).","permalink":"/docs/ref-arch/08N_yhbT/3"},{"id":"ref-arch/RA0031/vc-issuance-and-verification/id-ra0031-1","title":"DIV \u2013 Verifiable Credential Issuance and Verification","description":"This reference architecture describes how SAP Decentralized Identity Verification (DIV) issues, signs, and verifies W3C Verifiable Credentials and Verifiable Presentations on SAP BTP.","permalink":"/docs/ref-arch/08N_yhbT/1"},{"id":"ref-arch/RA0024/joule-iam/id-ra0024-2","title":"Identity and Access Management for SAP Joule","description":"This reference architecture describes the IAM related flows for SAP Joule with SAP Build Work Zone and via the SAP Cloud Identity Services.","permalink":"/docs/ref-arch/06ff6062dc/2"},{"id":"ref-arch/RA0019/identity-lifecycle/id-ra0019-2","title":"Identity lifecycle with SAP Cloud Identity Services","description":"This reference architecture describes the identity lifecycle flows for SAP SaaS via the SAP Cloud Identity Services.","permalink":"/docs/ref-arch/20c6b29b1e/2"},{"id":"ref-arch/RA0027/id-ra0027","title":"Log-Driven Security Operations with SAP Enterprise Threat Detection and SIEM/SOAR Platforms","description":"This reference architecture shows how SAP Enterprise Threat Detection provides log-driven security signals that are correlated in FortiSIEM and orchestrated through FortiSOAR to enable centralized monitoring incident investigation and automated response.","permalink":"/docs/ref-arch/d6e703646d"},{"id":"ref-arch/RA0019/id-ra0019","title":"SAP IAM integration with SAP Cloud Identity Services","description":"Design authentication and role management flows for SAP SaaS with SAP Cloud Identity Services.","permalink":"/docs/ref-arch/20c6b29b1e"},{"id":"ref-arch/RA0006/id-ra0006","title":"Secure connectivity with SAP Private Link service","description":"Secure SAP BTP-hyperscaler connectivity with SAP Private Link service, protecting sensitive data within private networks.","permalink":"/docs/ref-arch/a2f89cac57"},{"id":"ref-arch/RA0016/id-ra0016","title":"Secure Service Consumption Across Hyperscalers","description":"This architecture outlines a cloud-agnostic approach for securely consuming services offered by hyperscalers from applications running outside their environments.","permalink":"/docs/ref-arch/7e558be8f1"},{"id":"ref-arch/RA0016/secure-service-consumption-on-aws/id-ra0016-1","title":"Secure Service Consumption on AWS","description":"Securely access AWS services from external applications using robust identity and access management strategies.","permalink":"/docs/ref-arch/7e558be8f1/1"},{"id":"ref-arch/RA0016/secure-service-consumption-on-gcp/id-ra0016-2","title":"Secure Service Consumption on GCP","description":"Configure secure, keyless access to GCP resources using OIDC-based Workload Identity Federation. Workloads  authenticate without storing service account keys.","permalink":"/docs/ref-arch/7e558be8f1/2"},{"id":"ref-arch/RA0002/security/id-ra0002-8","title":"Security","description":"Security is crucial for enterprise applications and in the multi-region scenario, the security setup varies from service to service.","permalink":"/docs/ref-arch/81805673c0/8"},{"id":"ref-arch/RA0029/third-party-mcp-access/id-ra0029-10","title":"Third-Party MCP Access to SAP Solutions","description":"Guidance on accessing SAP solutions via third-party MCP servers, covering governance guardrails, OWASP MCP Top 10 risks, and SAP\'s recommended managed MCP approach via SAP Integration Suite and Joule Studio.","permalink":"/docs/ref-arch/ca1d2a3e/10"},{"id":"ref-arch/RA0014/id-ra0014","title":"Understanding Network Performance in a Multi Regional Solution","description":"Optimize multi-regional cloud solutions with insights into network design, provider usage, and service placement for superior performance.","permalink":"/docs/ref-arch/0ec83f98fe"},{"id":"ref-arch/RA0013/cloud-identity-services-bdc/id-ra0013-6","title":"Unifying Access Across SAP BDC with SAP Cloud Identity Services","description":"Unifying Access Across for SAP Business Data Cloud using SAP Cloud Identity Services: IAS for SSO (SAML/OIDC) and IPS for SCIM provisioning. Includes scenarios with/without Enterprise IdP, lifecycle, authorization mapping, and operations.","permalink":"/docs/ref-arch/f5b6b597a6/6"}],"unlisted":false}}')}}]);